#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int number; struct Node *next; } Node;

int main(void) {
    Node *head = NULL, *tail = NULL;
    for (int i = 1; i <= 13; i++) {
        Node *node = malloc(sizeof(*node));
        if (!node) return 1;
        node->number = i; node->next = NULL;
        if (tail) tail->next = node; else head = node;
        tail = node;
    }
    tail->next = head;
    Node *previous = tail, *current = head;
    while (current->next != current) {
        for (int count = 1; count < 3; count++) { previous = current; current = current->next; }
        previous->next = current->next;
        free(current); current = previous->next;
    }
    printf("%d\n", current->number);
    free(current);
    return 0;
}
